export const getUpdatePreferencesUrl = () => {




  return `/api/preferences`
}

/**
 * Currency (USD) and timezone (US Eastern) are fixed.
 * @summary Change display name or density
 */
export const updatePreferences = async (updatePreferencesRequest: UpdatePreferencesRequest,
    headers: UpdatePreferencesHeaders, options?: Parameters<typeof customFetch>[1]): Promise<Preferences> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return customFetch<Preferences>(getUpdatePreferencesUrl(),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json',...headers, ...getHeaders(options?.headers) },
    body: JSON.stringify(updatePreferencesRequest)
  }
);}





